from pathlib import Path
r=Path('yolk-survivors')
def edit(p,a,b):
 p=r/p;s=p.read_text(encoding='utf-8-sig');assert a in s,p;p.write_text(s.replace(a,b),encoding='utf-8')
edit('resources/unit_stats.gd','@export var pickup_range := 0.0','@export var weapon_range := 0.0\n@export var pickup_range := 0.0')
edit('resources/unit_stats.gd','\tpickup_range = 0','\tweapon_range = 0\n\tpickup_range = 0')
edit('resources/character_passives/character_passive.gd','"knockback": "Push"','"weapon_range": "Range", "knockback": "Push"')
edit('resources/character_passives/character_passive.gd','"experience_gain", "knockback")','"experience_gain", "knockback", "weapon_range")')
edit('scenes/ui/stats/stats_container.gd','const SECONDARY := [','const SECONDARY := ["weapon_range", ')
edit('scenes/ui/stats/stats_container.gd','const TITLES := {','const TITLES := {"weapon_range":"Range:", ')
edit('resources/items/weapons/item_weapon.gd','func get_range_description() -> String:\n\treturn format_number(stats.max_range)','func get_effective_range(player_stats: UnitStats = null) -> float:\n\treturn maxf(1.0, stats.max_range + (player_stats.weapon_range if player_stats else 0.0))\n\nfunc get_range_description(player_stats: UnitStats = null) -> String:\n\treturn format_number(get_effective_range(player_stats))')
p=r/'resources/items/weapons/item_weapon.gd';s=p.read_text(encoding='utf-8');s=s.replace('get_range_description(),','get_range_description(player_stats),').replace('get_range_description()','get_range_description(player_stats)');p.write_text(s,encoding='utf-8')
edit('scenes/weapons/weapon.gd','\tcollision.shape.radius = weapon_data.stats.max_range','\tcollision.shape = collision.shape.duplicate()\n\t_refresh_range()\n\tif get_parent() is Unit and not get_parent().stats.stats_changed.is_connected(_refresh_range):\n\t\tget_parent().stats.stats_changed.connect(_refresh_range)')
edit('scenes/weapons/weapon.gd','func can_use_weapon() -> bool:','func get_effective_range() -> float:\n\treturn data.get_effective_range(get_parent().stats if get_parent() is Unit else null)\n\nfunc _refresh_range() -> void:\n\tcollision.shape.radius = get_effective_range()\n\tspatial_target_deadline = 0.0\n\nfunc can_use_weapon() -> bool:')
edit('scenes/weapons/weapon.gd','data.stats.max_range * absf(collision.global_scale.x)','get_effective_range() * absf(collision.global_scale.x)')
for p in (r/'scenes/weapons').rglob('*.gd'):
 if p.name=='weapon.gd':continue
 s=p.read_text(encoding='utf-8-sig');s=s.replace('equipped.data.stats.max_range','equipped.get_effective_range()').replace('weapon.data.stats.max_range','weapon.get_effective_range()')
 if p.name=='melee_behaviour.gd':s=s.replace('stats.max_range','weapon.get_effective_range()')
 p.write_text(s,encoding='utf-8')
